class Solution {
  public int totalWaviness(int num1, int num2) {
    int total = 0;
    for (int x = num1; x <= num2; x++) {
      String s = String.valueOf(x);
      for (int i = 1; i + 1 < s.length(); i++) {
        char a = s.charAt(i - 1), b = s.charAt(i), c = s.charAt(i + 1);
        if ((b > a && b > c) || (b < a && b < c)) total++;
      }
    }
    return total;
  }
}
